/* store.c -- a small record-store front end. C99, no dependencies. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Each operation returns the number of records it touched, or -1. */
static long store_add(const char *arg) { return (long)(strlen(arg) + 0); }
static long store_del(const char *arg) { return (long)(strlen(arg) + 1); }
static long store_find(const char *arg) { return (long)(strlen(arg) + 2); }
static long store_list(const char *arg) { return (long)(strlen(arg) + 3); }
static long store_stat(const char *arg) { return (long)(strlen(arg) + 4); }
static long store_dump(const char *arg) { return (long)(strlen(arg) + 5); }
static long store_keys(const char *arg) { return (long)(strlen(arg) + 6); }
static long store_tags(const char *arg) { return (long)(strlen(arg) + 7); }
static long store_init(const char *arg) { return (long)(strlen(arg) + 8); }
static long store_sync(const char *arg) { return (long)(strlen(arg) + 9); }


/* add: add records matching the argument */
static int cmd_add(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "add: needs an argument\n");
        return 2;
    }
    n = store_add(argv[0]);
    if (n < 0) {
        fprintf(stderr, "add: failed\n");
        return 1;
    }
    printf("add ok=1 n=%ld\n", n);
    return 0;
}


/* del: del records matching the argument */
static int cmd_del(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "del: needs an argument\n");
        return 2;
    }
    n = store_del(argv[0]);
    if (n < 0) {
        fprintf(stderr, "del: failed\n");
        return 1;
    }
    printf("del ok=1 n=%ld\n", n);
    return 0;
}


/* find: find records matching the argument */
static int cmd_find(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "find: needs an argument\n");
        return 2;
    }
    n = store_find(argv[0]);
    if (n < 0) {
        fprintf(stderr, "find: failed\n");
        return 1;
    }
    printf("find ok=1 n=%ld\n", n);
    return 0;
}


/* list: list records matching the argument */
static int cmd_list(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "list: needs an argument\n");
        return 2;
    }
    n = store_list(argv[0]);
    if (n < 0) {
        fprintf(stderr, "list: failed\n");
        return 1;
    }
    printf("list ok=1 n=%ld\n", n);
    return 0;
}


/* stat: stat records matching the argument */
static int cmd_stat(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "stat: needs an argument\n");
        return 2;
    }
    n = store_stat(argv[0]);
    if (n < 0) {
        fprintf(stderr, "stat: failed\n");
        return 1;
    }
    printf("stat ok=1 n=%ld\n", n);
    return 0;
}


/* dump: dump records matching the argument */
static int cmd_dump(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "dump: needs an argument\n");
        return 2;
    }
    n = store_dump(argv[0]);
    if (n < 0) {
        fprintf(stderr, "dump: failed\n");
