    }
    printf("keys ok=1 n=%ld\n", n);
    return 0;
}


/* tags: tags records matching the argument */
static int cmd_tags(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "tags: needs an argument\n");
        return 2;
    }
    n = store_tags(argv[0]);
    if (n < 0) {
        fprintf(stderr, "tags: failed\n");
        return 1;
    }
    printf("tags ok=1 n=%ld\n", n);
    return 0;
}


/* init: init records matching the argument */
static int cmd_init(int argc, char **argv)
{
    long n;

    if (argc < 1) {
