        return 1;
    }
    printf("init ok=1 n=%ld\n", n);
    return 0;
}


/* sync: sync records matching the argument */
static int cmd_sync(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "sync: needs an argument\n");
        return 2;
    }
    n = store_sync(argv[0]);
    if (n < 0) {
        fprintf(stderr, "sync: failed\n");
        return 1;
    }
    printf("sync ok=1 n=%ld\n", n);
    return 0;
}


struct entry { const char *name; int (*fn)(int, char **); };

static const struct entry table[] = {
    { "add", cmd_add },
    { "del", cmd_del },
    { "find", cmd_find },
    { "list", cmd_list },
    { "stat", cmd_stat },
    { "dump", cmd_dump },
    { "keys", cmd_keys },
    { "tags", cmd_tags },
    { "init", cmd_init },
    { "sync", cmd_sync },
    { NULL, NULL }
};

int main(int argc, char **argv)
{
    int i;

    if (argc < 2) {
        fprintf(stderr, "usage: store COMMAND ARG\n");
        return 2;
    }
    for (i = 0; table[i].name; i++)
        if (strcmp(table[i].name, argv[1]) == 0)
            return table[i].fn(argc - 2, argv + 2);
    fprintf(stderr, "unknown command: %s\n", argv[1]);
    return 2;
}

